const b = $input.first().json.body || $input.first().json;
const cap = str => str ? str.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') : '';
return [{
  json: {
    freelancer_name: cap(b.freelancer_name),
    freelancer_email: b.freelancer_email || '',
    client_name: cap(b.client_name),
    client_email: b.client_email || '',
    client_company: cap(b.client_company || ''),
    service: cap(b.service || ''),
    project_description: b.project_description || '',
    deliverables: b.deliverables || '',
    budget: b.budget || '',
    deadline: b.deadline || '',
    timeline: b.timeline || '',
    bio: b.bio || '',
    past_result: b.past_result || '',
    portfolio_link: b.portfolio_link || '',
    hourly_rate: b.hourly_rate || ''
  }
}];

const proposal = items[0].json.choices[0].message.content;

const formData = $('Format Proposal Data').first().json;
if (!formData || !formData.freelancer_name) {
  throw new Error('No form data found in Format Proposal Data1 node');
}

const freelancerName = formData.freelancer_name;
const clientName = formData.client_name;
if (!clientName) throw new Error('client_name missing in form data');

const freelancerEmail = formData.freelancer_email || '';
const clientEmail = formData.client_email || '';
const clientCompany = formData.client_company || '';
const service = formData.service || '';
const budget = formData.budget || '';
const deadline = formData.deadline || '';

const today = new Date().toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});

const lines = proposal.split('\n');
let htmlBody = '';
let inList = false;
let currentSection = '';

function flushSection() {
  if (inList) {
    currentSection += '</ul>';
    inList = false;
  }
  if (currentSection) {
    // Table row wrapper — wkhtmltopdf respects page-break-inside on tr
    htmlBody += '<table style="width:100%;border-collapse:collapse;margin:0;padding:0;"><tr style="page-break-inside:avoid;"><td style="padding:0;border:none;vertical-align:top;display:block;">' + currentSection + '</td></tr></table>';
    currentSection = '';
  }
}

for (const line of lines) {
  const t = line.trim();

  if (!t) {
    if (inList) {
      currentSection += '</ul>';
      inList = false;
    }
    continue;
  }

  if (t.startsWith('## ')) {
    flushSection();
    currentSection = '<h2 style="color:#4f46e5;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-top:40px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #e5e7eb">' + t.slice(3) + '</h2>';
  }
  else if (t.startsWith('# ')) {
    currentSection += '<h1 style="font-size:24px;font-weight:400;margin:20px 0">' + t.slice(2) + '</h1>';
  }
  else if (t.startsWith('- ') || t.startsWith('* ')) {
    if (!inList) {
      currentSection += '<ul>';
      inList = true;
    }
    currentSection += '<li style="margin:6px 0;font-size:15px;color:#374151">' + t.slice(2) + '</li>';
  }
  else if (t.match(/^\d+\./)) {
    currentSection += '<p style="margin:10px 0;font-size:15px;color:#374151"><strong>' + t + '</strong></p>';
  }
  else {
    if (inList) {
      currentSection += '</ul>';
      inList = false;
    }
    currentSection += '<p style="margin:10px 0;font-size:15px;color:#374151">' + t + '</p>';
  }
}

if (inList) {
  currentSection += '</ul>';
  inList = false;
}

currentSection += 
  '<div style="margin-top:32px;padding-top:20px;border-top:2px solid #111827">' +
  '<div style="font-size:14px;font-weight:700;color:#111827;margin-bottom:4px">' + freelancerName + '</div>' +
  '<div style="font-size:13px;color:#6b7280">Independent Professional</div>' +
  '</div>' +
  '<div style="margin-top:20px;padding-top:12px;border-top:1px solid #e5e7eb;font-size:11px;color:#9ca3af">' +
  '<span>Confidential. Prepared exclusively for ' + clientName + '</span>' +
  '</div>';

flushSection();

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8">' +
  '<style>' +
  '*{box-sizing:border-box;margin:0;padding:0}' +
  'body{font-family:Georgia,serif;max-width:780px;margin:0 auto;color:#111827;line-height:1.8;padding:48px 56px;background:#fff}' +
  '.header{padding-bottom:28px;margin-bottom:40px;border-bottom:3px solid #4f46e5}' +
  '.header h1{font-size:32px;color:#111827;font-weight:400;margin-bottom:8px}' +
  '.meta{color:#6b7280;font-size:13px;line-height:2}' +
  'h2{color:#4f46e5;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-top:40px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #e5e7eb}' +
  'p{margin:10px 0;font-size:15px;color:#374151}' +
  'ul{margin:8px 0 8px 24px}' +
  'li{margin:6px 0;font-size:15px;color:#374151}' +
  'table{width:100%;border-collapse:collapse;margin:0;padding:0}' +
  'td{padding:0;border:none;vertical-align:top;display:block}' +
  '</style></head><body>' +
  '<div class="header">' +
  '<h1>Project Proposal</h1>' +
  '<div class="meta">Prepared by <strong>' + freelancerName + '</strong><br>For <strong>' + clientName + (clientCompany ? ' (' + clientCompany + ')' : '') + '</strong><br>' + today + '</div>' +
  '</div>' +
  htmlBody +
  '</body></html>';

return [{ json: { html, freelancer_email: freelancerEmail, client_email: clientEmail, freelancer_name: freelancerName, client_name: clientName, client_company: clientCompany, service, budget, deadline } }];
